## If you really need a **hand-rolled** custom protocol (non-PMTiles)

Below is a minimal, production-ready template you can copy-paste and adapt:

```js
/**
 * Register a custom protocol that fetches raw tile data from any HTTP(S) URL.
 * Works with MapLibre GL JS v4+.
 */
function registerMyTileProtocol() {
  // The name you will use in the style: "mytiles://…"
  const protocolName = 'mytiles';

  // The handler – async, receives params and an AbortController
  const handler = async (params, abortController) => {
    // `params.url` is the full URL after the protocol prefix.
    // Example style: url: "mytiles://https://example.com/tiles/{z}/{x}/{y}.pbf"
    const response = await fetch(params.url, {
      // Pass the abort signal so MapLibre can cancel the request.
      signal: abortController.signal,
      // Important for CORS: the server must allow the Range header.
      // No special headers needed for plain tile fetches.
    });

    if (!response.ok) {
      // Throwing aborts the tile request and makes MapLibre render a missing-tile placeholder.
      throw new Error(`Tile request failed (${response.status})`);
    }

    // Choose the most convenient representation.
    // For vector tiles you usually want an ArrayBuffer.
    const tileData = await response.arrayBuffer();

    // Optional: forward cache headers to the browser.
    const cacheControl = response.headers.get('Cache-Control');
    const expires = response.headers.get('Expires');

    return {
      data: tileData,
      // These are optional but useful if you control the server.
      cacheControl,
      expires,
    };
  };

  // Register it globally – do this once at app start.
  maplibregl.addProtocol(protocolName, handler);
}

// Call it before any MapLibre map is instantiated.
registerMyTileProtocol();
```

**How to use it in a style**

```json
{
  "sources": {
    "mySource": {
      "type": "vector",
      "url": "mytiles://https://my-static-host.com/tiles.pmtiles"
    }
  },
  "layers": [
    {
      "id": "myRoads",
      "type": "line",
      "source": "mySource",
      "source-layer": "road",
      "paint": { "line-color": "#ff6600", "line-width": 2 }
    }
  ]
}
```

*Remember to use `url:` (not `tiles:`) so the protocol can read the archive header and supply the correct zoom range.*

